class Solution {
    public int maximumNumberOfStringPairs(String[] words){
        Set<String> seen=new HashSet<>();
        int answer=0;
        for(String word:words){
            String reversed=""+word.charAt(1)+word.charAt(0);
            if(seen.contains(reversed))answer++;
            else seen.add(word);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumNumberOfStringPairs(words:Array<String>):Int{
        val seen=HashSet<String>();
        var answer=0;
        for(word in words){
            val reversed=word.reversed();
            if(reversed in seen)answer++ else seen.add(word)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public:int maximumNumberOfStringPairs(vector<string>& words){
        unordered_set<string> seen;
        int answer=0;
        for(string word:words){
            string reversed=word;
            reverse(reversed.begin(),reversed.end());
            if(seen.count(reversed))++answer;
            else seen.insert(word);
        }
        return answer;
    }
};
